import{G as e,W as t,n,rt as r}from"./chunks/framework.CMPLvzN_.js";var i=JSON.parse(`{"title":"排列组合问题","description":"","frontmatter":{},"headers":[],"relativePath":"数量关系/排列组合问题/index.md","filePath":"数量关系/排列组合问题/index.md"}`),a={name:`数量关系/排列组合问题/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="排列组合问题" tabindex="-1">排列组合问题 <a class="header-anchor" href="#排列组合问题" aria-label="Permalink to “排列组合问题”">​</a></h1><h2 id="基础排列组合" tabindex="-1">基础排列组合 <a class="header-anchor" href="#基础排列组合" aria-label="Permalink to “基础排列组合”">​</a></h2><ol><li><p>现在遇到的从n个元素中取k个元素，问有多少种方式？（$ k &lt; n $）</p><p>这种题型还可以具体分为<strong>不按顺序</strong>和<strong>按顺序</strong>两种</p><p>a. 不需要按照顺序 $$ C(n,k) = \\frac{n!}{k!(n-k)!} $$ 如果是从6个元素中取3个元素，则根据公式算得答案 $$ C(6,3) =\\frac{6!}{3!(6-3)!} = \\frac{6!}{3!3!} = \\frac{6<em>5</em>4<em>3</em>2<em>1}{（3</em>2<em>1）</em>2} =\\frac{6<em>5</em>4}{3<em>2</em>1} = 20 $$</p><p>b. 需要按照顺序 $$ P(n,k)=\\frac{n!}{(n-k)!} $$ 如果是从6个元素中取3个元素，则根据公式算得答案 $$ P(6,3) =\\frac{6!}{(6-3)!} = \\frac{6<em>5</em>4<em>3</em>2<em>1}{（6-3)!} = \\frac{6</em>5<em>4</em>3<em>2</em>1}{3!} = 6<em>5</em>4 = 120 $$</p></li></ol>`,3)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};